double GetGPMFSampleRate(size_t handle, uint32_t fourcc, uint32_t flags)
{
mp4object *mp4 = (mp4object *)handle;
if (mp4 == NULL) return 0.0;
GPMF_stream metadata_stream, *ms = &metadata_stream;
uint32_t teststart = 0;
uint32_t testend = mp4->indexcount;
double rate = 0.0;
if (mp4->indexcount < 1)
return 0.0;
if (mp4->indexcount > 3)
{
teststart++;
testend--;
}
uint32_t *payload = GetPayload(handle, NULL, teststart);
uint32_t payloadsize = GetPayloadSize(handle, teststart);
int32_t ret = GPMF_Init(ms, payload, payloadsize);
if (ret != GPMF_OK)
goto cleanup;
{
uint32_t startsamples = 0;
uint32_t endsamples = 0;
uint32_t missing_samples = 0;
while (ret == GPMF_OK && GPMF_OK != GPMF_FindNext(ms, fourcc, GPMF_RECURSE_LEVELS))
{
missing_samples = 1;
teststart++;
payload = GetPayload(handle, payload, teststart);
payloadsize = GetPayloadSize(handle, teststart);
ret = GPMF_Init(ms, payload, payloadsize);
}
if (missing_samples)
{
teststart++;
payload = GetPayload(handle, payload, teststart);
payloadsize = GetPayloadSize(handle, teststart);
ret = GPMF_Init(ms, payload, payloadsize);
}
if (ret == GPMF_OK)
{
uint32_t samples = GPMF_Repeat(ms);
GPMF_stream find_stream;
GPMF_CopyState(ms, &find_stream);
if (!(flags & GPMF_SAMPLE_RATE_PRECISE) && GPMF_OK == GPMF_FindPrev(&find_stream, GPMF_KEY_TOTAL_SAMPLES, GPMF_CURRENT_LEVEL))
{
startsamples = BYTESWAP32(*(uint32_t *)GPMF_RawData(&find_stream)) - samples;
payload = GetPayload(handle, payload, testend);
payloadsize = GetPayloadSize(handle, testend);
ret = GPMF_Init(ms, payload, payloadsize);
if (ret != GPMF_OK)
goto cleanup;
if (GPMF_OK == GPMF_FindNext(ms, fourcc, GPMF_RECURSE_LEVELS))
{
GPMF_CopyState(ms, &find_stream);
if (GPMF_OK == GPMF_FindPrev(&find_stream, GPMF_KEY_TOTAL_SAMPLES, GPMF_CURRENT_LEVEL))
{
endsamples = BYTESWAP32(*(uint32_t *)GPMF_RawData(&find_stream));
rate = (double)(endsamples - startsamples) / (mp4->metadatalength * ((double)(testend - teststart + 1)) / (double)mp4->indexcount);
goto cleanup;
}
}
rate = (double)(samples) / (mp4->metadatalength * ((double)(testend - teststart + 1)) / (double)mp4->indexcount);
}
else
{
uint32_t payloadpos = 0, payloadcount = 0;
double slope, top = 0.0, bot = 0.0, meanX = 0, meanY = 0;
uint32_t *repeatarray = malloc(mp4->indexcount * 4 + 4);
memset(repeatarray, 0, mp4->indexcount * 4 + 4);
samples = 0;
for (payloadpos = teststart; payloadpos < testend; payloadcount++, payloadpos++)
{
payload = GetPayload(handle, payload, payloadpos);
payloadsize = GetPayloadSize(handle, payloadpos);
ret = GPMF_Init(ms, payload, payloadsize);
if (ret != GPMF_OK)
goto cleanup;
if (GPMF_OK == GPMF_FindNext(ms, fourcc, GPMF_RECURSE_LEVELS))
{
GPMF_stream find_stream2;
GPMF_CopyState(ms, &find_stream2);
if (GPMF_OK == GPMF_FindNext(&find_stream2, fourcc, GPMF_CURRENT_LEVEL))
{
if (repeatarray)
{
float in, out;
do
{
samples++;
} while (GPMF_OK == GPMF_FindNext(ms, fourcc, GPMF_CURRENT_LEVEL));
repeatarray[payloadpos] = samples;
meanY += (double)samples;
GetPayloadTime(handle, payloadpos, &in, &out);
meanX += out;
}
}
else
{
uint32_t repeat = GPMF_Repeat(ms);
samples += repeat;
if (repeatarray)
{
float in, out;
repeatarray[payloadpos] = samples;
meanY += (double)samples;
GetPayloadTime(handle, payloadpos, &in, &out);
meanX += out;
}
}
}
}
if (repeatarray)
{
meanY /= (double)payloadcount;
meanX /= (double)payloadcount;
for (payloadpos = teststart; payloadpos < testend; payloadpos++)
{
float in, out;
GetPayloadTime(handle, payloadpos, &in, &out);
top += ((double)out - meanX)*((double)repeatarray[payloadpos] - meanY);
bot += ((double)out - meanX)*((double)out - meanX);
}
slope = top / bot;
#if 0
{
double intercept;
intercept = meanY - slope*meanX;
printf("%c%c%c%c start offset = %f (%.3fms)\n", PRINTF_4CC(fourcc), intercept, 1000.0 * intercept / slope);
}
#endif
rate = slope;
}
else
{
rate = (double)(samples) / (mp4->metadatalength * ((double)(testend - teststart + 1)) / (double)mp4->indexcount);
}
free(repeatarray);
goto cleanup;
}
}
}
cleanup:
if (payload)
{
FreePayload(payload);
payload = NULL;
}
return rate;
}

av_cold void ff_idctdsp_init(IDCTDSPContext *c, AVCodecContext *avctx)
{
const unsigned high_bit_depth = avctx->bits_per_raw_sample > 8;
if (avctx->lowres==1) {
c->idct_put  = ff_jref_idct4_put;
c->idct_add  = ff_jref_idct4_add;
c->idct      = ff_j_rev_dct4;
c->perm_type = FF_IDCT_PERM_NONE;
} else if (avctx->lowres==2) {
c->idct_put  = ff_jref_idct2_put;
c->idct_add  = ff_jref_idct2_add;
c->idct      = ff_j_rev_dct2;
c->perm_type = FF_IDCT_PERM_NONE;
} else if (avctx->lowres==3) {
c->idct_put  = ff_jref_idct1_put;
c->idct_add  = ff_jref_idct1_add;
c->idct      = ff_j_rev_dct1;
c->perm_type = FF_IDCT_PERM_NONE;
} else {
if (avctx->bits_per_raw_sample == 10 || avctx->bits_per_raw_sample == 9) {
if (avctx->codec_id == AV_CODEC_ID_MPEG4 && avctx->profile == FF_PROFILE_MPEG4_SIMPLE_STUDIO)
c->idct_put              = ff_simple_idct_put_int32_10bit;
else {
c->idct_put              = ff_simple_idct_put_int16_10bit;
c->idct_add              = ff_simple_idct_add_int16_10bit;
c->idct                  = ff_simple_idct_int16_10bit;
}
c->perm_type             = FF_IDCT_PERM_NONE;
} else if (avctx->bits_per_raw_sample == 12) {
c->idct_put              = ff_simple_idct_put_int16_12bit;
c->idct_add              = ff_simple_idct_add_int16_12bit;
c->idct                  = ff_simple_idct_int16_12bit;
c->perm_type             = FF_IDCT_PERM_NONE;
} else {
if (avctx->idct_algo == FF_IDCT_INT) {
c->idct_put  = ff_jref_idct_put;
c->idct_add  = ff_jref_idct_add;
c->idct      = ff_j_rev_dct;
c->perm_type = FF_IDCT_PERM_LIBMPEG2;
#if CONFIG_FAANIDCT
} else if (avctx->idct_algo == FF_IDCT_FAAN) {
c->idct_put  = ff_faanidct_put;
c->idct_add  = ff_faanidct_add;
c->idct      = ff_faanidct;
c->perm_type = FF_IDCT_PERM_NONE;
#endif
} else {
c->idct_put  = ff_simple_idct_put_int16_8bit;
c->idct_add  = ff_simple_idct_add_int16_8bit;
c->idct      = ff_simple_idct_int16_8bit;
c->perm_type = FF_IDCT_PERM_NONE;
}
}
}
c->put_pixels_clamped        = ff_put_pixels_clamped_c;
c->put_signed_pixels_clamped = put_signed_pixels_clamped_c;
c->add_pixels_clamped        = ff_add_pixels_clamped_c;
if (CONFIG_MPEG4_DECODER && avctx->idct_algo == FF_IDCT_XVID)
ff_xvid_idct_init(c, avctx);
if (ARCH_AARCH64)
ff_idctdsp_init_aarch64(c, avctx, high_bit_depth);
if (ARCH_ALPHA)
ff_idctdsp_init_alpha(c, avctx, high_bit_depth);
if (ARCH_ARM)
ff_idctdsp_init_arm(c, avctx, high_bit_depth);
if (ARCH_PPC)
ff_idctdsp_init_ppc(c, avctx, high_bit_depth);
if (ARCH_X86)
ff_idctdsp_init_x86(c, avctx, high_bit_depth);
if (ARCH_MIPS)
ff_idctdsp_init_mips(c, avctx, high_bit_depth);
ff_init_scantable_permutation(c->idct_permutation,
c->perm_type);
}

int start_c2c_connection(uint16_t clnet_remote_port0, const char *remote_address0, const unsigned char *ifname,
                         const char *local_address, bool verbose, app_ur_conn_info *clnet_info_probe,
                         app_ur_conn_info *clnet_info1, uint16_t *chn1, app_ur_conn_info *clnet_info1_rtcp,
                         uint16_t *chn1_rtcp, app_ur_conn_info *clnet_info2, uint16_t *chn2,
                         app_ur_conn_info *clnet_info2_rtcp, uint16_t *chn2_rtcp) {

  ioa_addr relay_addr1;
  ioa_addr relay_addr1_rtcp;

  ioa_addr relay_addr2;
  ioa_addr relay_addr2_rtcp;

  *chn1 = 0;
  *chn2 = 0;
  if (chn1_rtcp) {
    *chn1_rtcp = 0;
  }
  if (chn2_rtcp) {
    *chn2_rtcp = 0;
  }

  /* Probe: */

  if (clnet_connect(clnet_remote_port0, remote_address0, ifname, local_address, verbose, clnet_info_probe) < 0) {
    exit(-1);
  }

  uint16_t clnet_remote_port = clnet_remote_port0;
  char remote_address[1025];
  STRCPY(remote_address, remote_address0);

  clnet_allocate(verbose, clnet_info_probe, &relay_addr1, default_address_family, remote_address, &clnet_remote_port);

  if (rare_event()) {
    return 0;
  }

  /* Real: */

  if (clnet_connect(clnet_remote_port, remote_address, ifname, local_address, verbose, clnet_info1) < 0) {
    exit(-1);
  }

  if (!no_rtcp) {
    if (clnet_connect(clnet_remote_port, remote_address, ifname, local_address, verbose, clnet_info1_rtcp) < 0) {
      exit(-1);
    }
  }

  if (passive_tcp) {
    clnet_info2->is_peer = true;
  }

  if (clnet_connect(clnet_remote_port, remote_address, ifname, local_address, verbose, clnet_info2) < 0) {
    exit(-1);
  }

  if (!no_rtcp) {
    if (clnet_connect(clnet_remote_port, remote_address, ifname, local_address, verbose, clnet_info2_rtcp) < 0) {
      exit(-1);
    }
  }

  if (!no_rtcp) {

    if (clnet_allocate(verbose, clnet_info1, &relay_addr1, default_address_family, NULL, NULL) < 0) {
      exit(-1);
    }

    if (rare_event()) {
      return 0;
    }

    if (clnet_allocate(verbose, clnet_info1_rtcp, &relay_addr1_rtcp, default_address_family, NULL, NULL) < 0) {
      exit(-1);
    }

    if (rare_event()) {
      return 0;
    }

    if (clnet_allocate(verbose, clnet_info2, &relay_addr2, default_address_family, NULL, NULL) < 0) {
      exit(-1);
    }

    if (rare_event()) {
      return 0;
    }

    if (clnet_allocate(verbose, clnet_info2_rtcp, &relay_addr2_rtcp, default_address_family, NULL, NULL) < 0) {
      exit(-1);
    }

    if (rare_event()) {
      return 0;
    }
  } else {

    if (clnet_allocate(verbose, clnet_info1, &relay_addr1, default_address_family, NULL, NULL) < 0) {
      exit(-1);
    }
    if (rare_event()) {
      return 0;
    }
    if (!(clnet_info2->is_peer)) {
      if (clnet_allocate(verbose, clnet_info2, &relay_addr2, default_address_family, NULL, NULL) < 0) {
        exit(-1);
      }
      if (rare_event()) {
        return 0;
      }
    } else {
      addr_cpy(&(clnet_info2->remote_addr), &relay_addr1);
      addr_cpy(&relay_addr2, &(clnet_info2->local_addr));
    }
  }

  if (!do_not_use_channel) {
    if (turn_channel_bind(verbose, chn1, clnet_info1, &relay_addr2) < 0) {
      exit(-1);
    }

    if (extra_requests) {
      const char *sarbaddr = "164.156.178.190";
      if (turn_random() % 2 == 0) {
        sarbaddr = "2001::172";
      }
      ioa_addr arbaddr;
      make_ioa_addr((const uint8_t *)sarbaddr, 333, &arbaddr);
      const int maxi = (unsigned short)turn_random() % EXTRA_CREATE_PERMS;
      for (int i = 0; i < maxi; i++) {
        uint16_t chni = 0;
        int port = (unsigned short)turn_random();
        if (port < 1024) {
          port += 1024;
        }
        addr_set_port(&arbaddr, port);
        uint8_t *const u = (uint8_t *)&(arbaddr.s4.sin_addr);
        u[(unsigned short)turn_random() % 4] = u[(unsigned short)turn_random() % 4] + 1;
        // char sss[128];
        // addr_to_string(&arbaddr,(uint8_t*)sss);
        // printf("%s: 111.111: %s\n",__FUNCTION__,sss);
        turn_channel_bind(verbose, &chni, clnet_info1, &arbaddr);
      }
    }

    if (rare_event()) {
      return 0;
    }

    if (extra_requests) {
      const char *sarbaddr = "64.56.78.90";
      if (turn_random() % 2 == 0) {
        sarbaddr = "2001::172";
      }
      ioa_addr arbaddr[EXTRA_CREATE_PERMS];
      make_ioa_addr((const uint8_t *)sarbaddr, 333, &arbaddr[0]);
      const int maxi = (unsigned short)turn_random() % EXTRA_CREATE_PERMS;
      for (int i = 0; i < maxi; i++) {
        if (i > 0) {
          addr_cpy(&arbaddr[i], &arbaddr[0]);
        }
        addr_set_port(&arbaddr[i], (unsigned short)turn_random());
        uint8_t *const u = (uint8_t *)&(arbaddr[i].s4.sin_addr);
        u[(unsigned short)turn_random() % 4] = u[(unsigned short)turn_random() % 4] + 1;
        // char sss[128];
        // addr_to_string(&arbaddr[i],(uint8_t*)sss);
        // printf("%s: 111.111: %s\n",__FUNCTION__,sss);
      }
      turn_create_permission(verbose, clnet_info1, arbaddr, maxi);
    }

    if (!no_rtcp) {
      if (turn_channel_bind(verbose, chn1_rtcp, clnet_info1_rtcp, &relay_addr2_rtcp) < 0) {
        exit(-1);
      }
    }
    if (rare_event()) {
      return 0;
    }
    if (turn_channel_bind(verbose, chn2, clnet_info2, &relay_addr1) < 0) {
      exit(-1);
    }
    if (rare_event()) {
      return 0;
    }
    if (!no_rtcp) {
      if (turn_channel_bind(verbose, chn2_rtcp, clnet_info2_rtcp, &relay_addr1_rtcp) < 0) {
        exit(-1);
      }
    }
    if (rare_event()) {
      return 0;
    }
  } else {

    if (turn_create_permission(verbose, clnet_info1, &relay_addr2, 1) < 0) {
      exit(-1);
    }

    if (extra_requests) {
      const char *sarbaddr = "64.56.78.90";
      if (turn_random() % 2 == 0) {
        sarbaddr = "2001::172";
      }
      ioa_addr arbaddr;
      make_ioa_addr((const uint8_t *)sarbaddr, 333, &arbaddr);
      const int maxi = (unsigned short)turn_random() % EXTRA_CREATE_PERMS;
      for (int i = 0; i < maxi; i++) {
        addr_set_port(&arbaddr, (unsigned short)turn_random());
        uint8_t *const u = (uint8_t *)&(arbaddr.s4.sin_addr);
        u[(unsigned short)turn_random() % 4] = u[(unsigned short)turn_random() % 4] + 1;
        // char sss[128];
        // addr_to_string(&arbaddr,(uint8_t*)sss);
        // printf("%s: 111.111: %s\n",__FUNCTION__,sss);
        turn_create_permission(verbose, clnet_info1, &arbaddr, 1);
      }
    }

    if (rare_event()) {
      return 0;
    }
    if (!no_rtcp) {
      if (turn_create_permission(verbose, clnet_info1_rtcp, &relay_addr2_rtcp, 1) < 0) {
        exit(-1);
      }
    }
    if (rare_event()) {
      return 0;
    }
    if (!(clnet_info2->is_peer)) {
      if (turn_create_permission(verbose, clnet_info2, &relay_addr1, 1) < 0) {
        exit(-1);
      }
      if (rare_event()) {
        return 0;
      }
    }
    if (!no_rtcp) {
      if (turn_create_permission(verbose, clnet_info2_rtcp, &relay_addr1_rtcp, 1) < 0) {
        exit(-1);
      }
    }
    if (rare_event()) {
      return 0;
    }
  }

  addr_cpy(&(clnet_info1->peer_addr), &relay_addr2);
  if (!no_rtcp) {
    addr_cpy(&(clnet_info1_rtcp->peer_addr), &relay_addr2_rtcp);
  }
  addr_cpy(&(clnet_info2->peer_addr), &relay_addr1);
  if (!no_rtcp) {
    addr_cpy(&(clnet_info2_rtcp->peer_addr), &relay_addr1_rtcp);
  }

  return 0;
}

